export function searchSkillIndex(keyword = '') {
  const kw = keyword.trim().toLowerCase();
  if (!kw) return localSkillIndex;
  return localSkillIndex.filter(item =>
    [item.name, item.displayName, item.description, item.category, item.author].join(' ').toLowerCase().includes(kw));
}

export function searchMarket(keyword = '', category = 'all') {
  const kw = keyword.trim().toLowerCase();
  return skillhubMarket.filter(item => {
    if (category !== 'all' && item.category !== category) return false;
    if (!kw) return true;
    return [item.name, item.displayName, item.description, item.category, item.author].join(' ').toLowerCase().includes(kw);
  });
}

export const marketCategories = ['all', ...[...new Set(skillhubMarket.map(x => x.category))]];
